window.kbPageData["views/entry/k-9b47841113e622e6"] = {"key":"entry/k-9b47841113e622e6","state":{"route":"entry/k-9b47841113e622e6"},"node":{"id":"k-9b47841113e622e6","mode":"k","title":"行政诉讼原告资格","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["行政诉讼原告资格中的相对人和利害关系人"],"qs":["江苏 2023 B类 行测#19"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"行政行为的相对人，以及其他与被诉行政行为有利害关系的公民、法人或其他组织，有权提起行政诉讼。被诉行为涉及其相邻权，或者其为维护自身合法权益投诉而有处理职责的机关作出或未作出处理，均可构成利害关系。","review":{"definition":"行政行为的相对人，以及其他与被诉行政行为有利害关系的公民、法人或其他组织，有权提起行政诉讼。被诉行为涉及其相邻权，或者其为维护自身合法权益投诉而有处理职责的机关作出或未作出处理，均可构成利害关系。","explanation":"第19题中，陈某起诉所针对的是街道办未执行区政府的强拆批复。原案法院以该诉请不属于行政诉讼受案范围、陈某不具有原告资格为由裁定驳回。法院供稿的案例评析指出，街道办按批复履行上级命令的行为缺少独立的法律效果，陈某作为小区居民多次反映违建的事实，不能据此取得这项诉请的原告资格。若另行针对涉及自身相邻权的行政行为，或针对有处理职责机关对权益投诉的处理起诉，须就相应被诉行为判断利害关系。","references":[{"source":"web-e498a67eed717441","location":"第二十五条第一款","quote":"行政行为的相对人以及其他与行政行为有利害关系的公民"},{"source":"web-47f9e3dd8cd81c8c","location":"第十二条第一项、第五项","quote":"被诉的行政行为涉及其相邻权或者公平竞争权的"},{"source":"web-8f9d20696d66dd54","location":"裁判、评析第三部分","quote":"且陈某强不具有原告资格"}],"evidence":"陈某认为，街道办未执行区政府的批复，遂提起诉讼。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 B类 行测#19":{"paper":"江苏 2023 B类 行测","n":19,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",3],"asrc":["b08f2713d73015eac675.pdf",8],"card":"a980fa5fcb5dfb5bac46689a","links":[{"id":"k-9b47841113e622e6","role":"解题依据","why":"居民举报违建后，仍须根据其是否为行政相对人或与被诉行政行为有利害关系判断原告资格。"}]}},"terms":{},"references":{"web-e498a67eed717441":{"name":"《中华人民共和国行政诉讼法》（2017年修正）","url":"https://gdca.miit.gov.cn/zwgk/zcwj/flfg/art/2020/art_58ff765df1624075b6da5507fe438b38.html"},"web-47f9e3dd8cd81c8c":{"name":"《最高人民法院关于适用〈中华人民共和国行政诉讼法〉的解释》","url":"https://www.court.gov.cn/zixun/xiangqing/80342.html"},"web-8f9d20696d66dd54":{"name":"《人民法院报》陈某强诉重庆江北区石马河街道办履行强拆批复案","url":"https://www.sdcourt.gov.cn/wfhtqfy/443063/443232/7281449/index.html"}},"topics":[],"units":{"k-9b47841113e622e6":[["江苏 2023 B类 行测#19"]]}};
